  5344  tune_call(Node* node, ScanEnv* env, int state)
  5345  {
  5346    int r;
  5347
  5348    switch (NODE_TYPE(node)) {
  5349    case NODE_LIST:
  5350    case NODE_ALT:
  5351      do {
  5352        r = tune_call(NODE_CAR(node), env, state);
  5353      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5354      break;
  5355
  5356    case NODE_QUANT:
  5357      if (QUANT_(node)->upper == 0)
  5358        state |= IN_ZERO_REPEAT;
  5359
  5360      r = tune_call(NODE_BODY(node), env, state);
  5361      break;
  5362
  5363    case NODE_ANCHOR:
  5364      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5365        r = tune_call(NODE_BODY(node), env, state);
  5366      else
  5367        r = 0;
  5368      break;
  5369
  5370    case NODE_BAG:
  5371      {
  5372        BagNode* en = BAG_(node);
  5373
  5374        if (en->type == BAG_MEMORY) {
  5375          if ((state & IN_ZERO_REPEAT) != 0) {
  5376            NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5377            BAG_(node)->m.entry_count--;
  5378          }
  5379          r = tune_call(NODE_BODY(node), env, state);
  5380        }
  5381        else if (en->type == BAG_IF_ELSE) {
  5382          r = tune_call(NODE_BODY(node), env, state);
  5383          if (r != 0) return r;
  5384          if (IS_NOT_NULL(en->te.Then)) {
  5385            r = tune_call(en->te.Then, env, state);
  5386            if (r != 0) return r;
  5387          }
  5388          if (IS_NOT_NULL(en->te.Else))
  5389            r = tune_call(en->te.Else, env, state);
  5390        }
  5391        else
  5392          r = tune_call(NODE_BODY(node), env, state);
  5393      }
  5394      break;
  5395
  5396    case NODE_CALL:
  5397      if ((state & IN_ZERO_REPEAT) != 0) {
  5398        NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5399        CALL_(node)->entry_count--;
  5400      }
  5401
  5402      r = tune_call_node_call(CALL_(node), env, state);
  5403      break;
  5404
  5405    default:
  5406      r = 0;
  5407      break;
  5408    }
  5409
  5410    return r;
  5411  }
